from pathlib import Path
from html.parser import HTMLParser
from PIL import Image,ImageDraw,ImageFont
import json,html,zipfile

ROOT=Path(__file__).resolve().parent
DATA=json.loads((ROOT/'Study.json').read_text(encoding='utf-8-sig'))
SOURCES={
 'SOM':('SOM — Manhattan West, public space and breezeway','https://www.som.com/projects/manhattan-west-development/'),
 'SkyHabitat':('Safdie Architects — Sky Habitat','https://www.safdiearchitects.com/projects/sky-habitat-residential-development'),
 'Valley':('MVRDV — Valley','https://www.mvrdv.com/projects/233/valley'),
 'Parking':('Herzog & de Meuron — 1111 Lincoln Road','https://www.herzogdemeuron.com/projects/279-1111-lincoln-road/'),
 'AHMM':('AHMM — White Collar Factory','https://www.ahmm.co.uk/projects/office/white-collar-factory/'),
 'Silo':('MVRDV — Frøsilo','https://www.mvrdv.com/projects/143/fr%C3%B8s')}
def image(c):return f'{c["id"]}-concept'+('-v2' if c['id']==11 else '')+'.png'
def ref(key):title,url=SOURCES[key];return f'<a href="{url}">{html.escape(title)}</a>'

def city_plan():
 # A district composition diagram, deliberately not a measured map layout.
 blocks=[(70,80,300,230,'11 Crownline Offices','60 m landmark','#55cdb5'),(570,80,340,250,'12 Lantern Court','45 m / courtyard','#ff947e'),(70,490,320,220,'14 Parking Tower','30 m / open decks','#b7a0ed'),(590,490,320,220,'16 City Hall','42 m / public square','#ffd17d')]
 svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="830" viewBox="0 0 1000 830"><rect width="1000" height="830" fill="#14233a"/><text x="45" y="40" font-size="25" font-family="sans-serif" fill="white">A four-building city test district</text><path d="M25 395 H975 M475 65 V755" stroke="#607589" stroke-width="78"/><path d="M25 395 H975 M475 65 V755" stroke="#c7d2db" stroke-width="3" stroke-dasharray="14 14"/>']
 for x,y,w,h,title,sub,col in blocks:
  svg.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="9" fill="{col}"/><text x="{x+18}" y="{y+34}" fill="#14233a" font-size="21" font-family="sans-serif">{title}</text><text x="{x+18}" y="{y+64}" fill="#14233a" font-size="17" font-family="sans-serif">{sub}</text>')
 svg.append('<rect x="675" y="180" width="125" height="110" fill="#14233a"/><path d="M735 290 V340" stroke="#89edda" stroke-width="14"/><path d="M70 250 H370 M590 640 H910" stroke="#89edda" stroke-width="14"/><text x="45" y="795" font-size="18" font-family="sans-serif" fill="white">Schematic only · mint paths: through-buildings · not to scale or jump-distance validated</text></svg>')
 (ROOT/'CityBlockSketch.svg').write_text(''.join(svg),encoding='utf-8')

def build():
 esc=html.escape
 figures=[];rows=[]
 for c in DATA['concepts']:
  p=ROOT/image(c)
  with Image.open(p) as im:im.verify()
  body=''.join(f'<h3>{title}</h3><p>{esc(c[key])}</p>' for key,title in [('identity','City identity'),('open','Open and sheltered space'),('structure','Physical section strategy'),('routes','Movement'),('damage','How damage changes the building'),('cost','Keeping the cost controlled'),('test','First prototype checks')])
  figures.append(f'<article id="b{c["id"]}"><p class="eyebrow">{esc(c["risk"])} prototype risk · {c["height"]} m study height</p><h2>{c["id"]} {esc(c["name"])}</h2><a href="{image(c)}"><img loading="lazy" src="{image(c)}" alt="Two concept views of {esc(c["name"])}: street silhouette and playable open space"></a><p class="meta">AI concept art, not a screenshot or measured collision plan. Click to enlarge both views.</p>{body}<p class="meta">Architectural references for spatial ideas, not proof of loose-block stability: {" · ".join(ref(s) for s in c["sources"])}</p></article>')
  rows.append(f'<tr><td><a href="#b{c["id"]}">{c["id"]} {esc(c["name"])}</a></td><td>{c["height"]} m</td><td>{esc(c["bodies"])}</td><td>{esc(c["colliders"])}</td></tr>')
 style='''body{margin:0;background:#112037;color:#eaf1fa;font:18px/1.65 system-ui,sans-serif}main{max-width:1280px;margin:auto;padding:44px 26px}h1{font-size:clamp(38px,5vw,66px);line-height:1.08}h2{font-size:32px;line-height:1.2}h3{font-size:20px;color:#a0e8ce;margin-bottom:4px}a{color:#91daff}img{display:block;width:100%;border-radius:12px}section,article{padding:36px 0;border-bottom:1px solid #354760;scroll-margin-top:20px}.meta,.eyebrow{color:#abc0d6}.eyebrow{text-transform:uppercase;font-size:14px;letter-spacing:1.6px}.notice{background:#383135;border-left:5px solid #ffd37b;padding:20px}p{max-width:1100px}li{margin:10px 0}table{width:100%;border-collapse:collapse}td,th{padding:12px;text-align:left;border-bottom:1px solid #354760;font-size:16px}.scroll{overflow:auto}nav{display:flex;gap:8px;flex-wrap:wrap}nav a{background:#23384f;padding:7px 10px;border-radius:8px;font-size:15px}code{color:#ffd37b}small{color:#abc0d6}@media(max-width:720px){main{padding:25px 16px}h2{font-size:27px}}'''
 nav=''.join(f'<a href="#b{c["id"]}">{c["id"]} {esc(c["name"])}</a>' for c in DATA['concepts'])
 intro=f'''<p class="eyebrow">Deadly Jenga · City-building concepts 11–20 · 25 October 2026</p><h1>A city made of<br>playable buildings.</h1><p>Ten new families with recognizable office, apartment, hotel, parking, civic and industrial identities. They keep the large-section physics approach, but use street entrances, repeated bays, rooflines and deliberately shaped voids to read as an urban district. Each image pairs a full exterior with a closer view of a usable open or sheltered space.</p><div class="notice"><b>Concepts, not implemented maps.</b> The twenty views are built-in imagegen illustrations in ten paired images. They are not Unity captures, dimensionally reliable plans or physics results. The written proposals govern where supports, floor openings, pads and clear climbing surfaces must go. Railings, planting, lights, background buildings and street props in the art are illustrative visual dressing, not an instruction to add matching physics objects. No new tower was simulated.</div><p><a href="ContactSheet.jpg">All ten paired images at a glance</a> · <a href="CityBuildingStudy.zip">Download pictures and study</a> · <a href="ArtPrompts.json">Exact image prompts</a></p><nav>{nav}</nav>
 <section><h2>What makes this set feel more like a city</h2><p><b>A base, a middle and a top.</b> A public portico or loading court meets the street, a consistent rhythm explains the occupied floors, and a roof or crown gives the building a recognizable silhouette. These large cues can carry the identity without small brickwork or a wall of individual window objects.</p><p><b>Give the voids an architectural role.</b> An apartment courtyard, a hotel atrium, a parking deck, a concourse and a roofed civic square all count as interiors or urban spaces even though much of their boundary remains open. The aim is a mix of deep alcoves, sheltered halls, visible upper floors and clear outward views, rather than an entirely sealed building or an entirely exposed scaffold.</p><p><b>Use streets and shared edges.</b> Entrances should face a connected street, podiums should offer through-passages, and roof heights should vary. An occasional high bridge is valuable, but an entire city joined only by identical skywalks would recreate the repetitive festival problem.</p></section>
 <section><h2>Research translated into game spaces</h2><p>Herzog & de Meuron describes 1111 Lincoln Road as a fully open concrete structure. It is a useful precedent for an urban-looking building whose slabs, supports and generous openings are the architecture; enclosed rooms are not required for city identity. The parking proposal borrows that openness, not the real building's engineering as a proof of loose-stack stability. {ref('Parking')}.</p><p>Safdie's Sky Habitat combines homes, terraces and shared outdoor space. MVRDV's Valley offers another reference for contrasting a city-facing building mass with more open, irregular occupied space. The apartment and garden proposals translate those ideas into a few repeated, balanced game sections; they do not assume real-world ties or cantilevers exist in the loose physics assembly. {ref('SkyHabitat')} · {ref('Valley')}.</p><p>SOM's Manhattan West project includes a carved-out elevated breezeway extending public space through a building. That informs the office podium and exchange: a passage through the base can help make a city connected and legible. AHMM's White Collar Factory is a reference for a flexible work-building identity expressed through generous structural space. {ref('SOM')} · {ref('AHMM')}.</p><p>MVRDV's Frøsilo reuses silo structures as the core of housing. Here the utility-tower silhouette is reinterpreted as a hollow playable crown on open supports. It is an analogy for useful occupied space in an industrial form, not a claim that the proposed water tower duplicates that project. {ref('Silo')}.</p></section>'''
 constraints='''<section><h2>Physics and movement rules retained</h2><ul><li><b>Several floors per moving section.</b> Integrate piers, structural walls, stairs and landings into each cassette, then separate meaningful story bands and a few supports. A window bay or decorative clock hand does not need its own Rigidbody.</li><li><b>Use actual bearing lines.</b> A tower above a concourse must load the piers below. A skybridge is a loose supported route unless an explicit connection is designed; it cannot be silently counted as a tensile brace.</li><li><b>Keep designated climb faces clear.</b> Floors, balconies, cornices and rails must stay behind the chosen rib's climbing plane. Broad setback roofs should be explicit top-out/rest locations. The art is not a clearance test.</li><li><b>Reserve stairs' floor openings.</b> Include a flat pad before turning at both ends of each flight. Test with the real capsule; the current motor's default step offset is only 2.5 cm at player scale 0.5, so apparently minor slab lips matter.</li><li><b>Preserve meaningful wall-backed cover.</b> Open space does not require every floor to be exposed from every direction. A few broad panels and deep alcoves create contrast without many little rooms.</li><li><b>Plan a damaged building as another playspace.</b> Leave side exits and space for a large section to tilt. A convenient new ramp or a bridge landing is a hypothesis to test, not a guaranteed collapse animation.</li><li><b>Keep the image's dressing out of the physics budget.</b> Rail details, planting, lane paint and window shading can be visual-only. Do not add a live light or a collider for every small feature shown by the artist.</li></ul></section>'''
 budgets=f'''<section><h2>Early authoring allowances</h2><p>{esc(DATA['budgetStatus'])} Paired buildings and the station are budgeted as whole complexes. Heights are nominal study targets; image generation does not enforce floor counts or exact scale.</p><div class="scroll"><table><thead><tr><th>Building / complex</th><th>Study height</th><th>Moving bodies</th><th>Collision shapes</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div><p>These proposals generally use fewer large structural parts rather than independently simulated facades. That trades some fine-grained destruction for traversable interiors and clearer collapse bands. Many colliders can still make a small number of bodies expensive. The previous Foundry measurements also showed substantial bot-planning cost, so no FPS or Quest-readiness claim follows from these allowances.</p></section>'''
 mix='''<section><h2>How I would compose the first city district</h2><p><b>Start with Crownline Offices, Lantern Court Apartments, Switchback Parking Tower and Lantern City Hall.</b> Use the offices as the tallest landmark, the apartment court as a residential block, the parking deck as an open movement playground and City Hall as a public-space anchor. Their nominal heights of 60, 45, 30 and 42 m give a more varied roofline than four equal-height towers.</p><a href="CityBlockSketch.svg"><img src="CityBlockSketch.svg" alt="Schematic four-building street district, not a measured map"></a><p>That four-building selection has a combined provisional allowance of 84–136 moving bodies and 640–1,040 collision shapes. This is arithmetic on the design ranges, not a measured implementation. Leave room for streets, useful fallen sections and sightlines rather than filling every gap with another high-rise.</p><p>Then add Foundry Lofts and Harbor Waterworks along one edge to create an industrial/waterfront district. The hotel can form a denser mid-rise block. Use either Central Exchange or Gateway Headquarters as a major additional anchor after profiling; starting with both large complexes could overpopulate the scene.</p><p>Connect at multiple scales: through-passages at ground level, occasional short crossings around lower roofs, and one memorable higher bridge. Jump and drop distances must be measured with the selected movement rules before placing the final streets. The sketch deliberately makes no jump-distance claim.</p></section>
 <section><h2>The minimum useful prototype pass</h2><ol><li>Build one two- to four-floor section with its actual bays, stair opening, pads and collision. Confirm the gray box is useful without facade art.</li><li>Test its real mass and centre of mass on intended bearing patches, then two sections stacked. Check the entire upper assembly at every separable band.</li><li>Walk stairs in both directions, test top-outs and every climbing band, and test passing/escaping with more than one character.</li><li>Remove or displace one support and inspect several plausible damaged states. A courtyard full of trapped players or continuously jittering debris is a failed version, even if the screenshot looks good.</li><li>Only then increase height, populate bots and compare quiet and tsunami runs with consistent settings. Test on Quest before approving a device budget.</li></ol><p>No Unity box, lane, scene, Core contract, project setting or package was changed for this study. The additions are confined to ArtDirection/CityTowerStudy-20261025.</p></section>'''
 page=f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Deadly Jenga — City-like building study</title><style>{style}</style><main>{intro}{constraints}{budgets}{"".join(figures)}{mix}<section><h2>Sources and files</h2><ul>{"".join("<li>"+ref(k)+"</li>" for k in SOURCES)}</ul><p>Original design synthesis and built-in imagegen art. <a href="Study.json">Structured specifications</a> · <a href="ArtPrompts.json">Original prompt set</a> · <a href="EditPrompt.json">Annotation correction prompt</a> · <a href="CityBuildingStudy.zip">Complete download</a></p></section></main></html>'
 city_plan();(ROOT/'index.html').write_text(page,encoding='utf-8')
 sheet=Image.new('RGB',(1800,5*610),'#14233a');draw=ImageDraw.Draw(sheet);f=ImageFont.truetype('C:/Windows/Fonts/segoeui.ttf',23)
 for i,c in enumerate(DATA['concepts']):
  with Image.open(ROOT/image(c)) as im:
   im.thumbnail((880,555));x=i%2*900+10;y=i//2*610+40;sheet.paste(im,(x,y));draw.text((x,y-33),f'{c["id"]} {c["name"]}',fill='white',font=f)
 sheet.save(ROOT/'ContactSheet.jpg',quality=93)
 files=[ROOT/image(c) for c in DATA['concepts']]+[ROOT/n for n in ['index.html','Study.json','ArtPrompts.json','EditPrompt.json','ContactSheet.jpg','CityBlockSketch.svg']]
 with zipfile.ZipFile(ROOT/'CityBuildingStudy.zip','w',zipfile.ZIP_DEFLATED) as z:
  for p in files:z.write(p,p.name)
 class Check(HTMLParser):
  def handle_starttag(self,tag,attrs):
   for k,v in attrs:
    if k in ('src','href') and not v.startswith(('#','https:','http:')):assert (ROOT/v).is_file(),v
 Check().feed(page)
 with zipfile.ZipFile(ROOT/'CityBuildingStudy.zip') as z:assert z.testzip() is None
 assert len(DATA['concepts'])==10
 print('PASS: ten concepts / twenty paired views, image integrity, local gallery links and archive integrity.')
if __name__=='__main__':build()
